      untitledDeck: "\uC81C\uBAA9 \uC5C6\uB294 \uD504\uB808\uC820\uD14C\uC774\uC158",
      autosaveFoundTitle: "\uC790\uB3D9 \uBCF5\uAD6C \uBC84\uC804 \uBC1C\uACAC",
      autosaveDiskNewer:
        "\uCC38\uACE0: \uC774 \uBCF5\uAD6C \uC0AC\uBCF8\uC774 \uC800\uC7A5\uB41C \uD6C4 \uB514\uC2A4\uD06C\uC758 \uD30C\uC77C\uC774 \uC218\uC815\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uBCF5\uC6D0\uD558\uBA74 \uADF8 \uCD5C\uC2E0 \uBCC0\uACBD \uB0B4\uC6A9\uC774 \uB300\uCCB4\uB429\uB2C8\uB2E4.",
      autosaveFoundBody:
        "\uB9C8\uC9C0\uB9C9 \uC138\uC158\uC5D0 \uC800\uC7A5\uB418\uC9C0 \uC54A\uC740 \uBCC0\uACBD \uB0B4\uC6A9\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uC790\uB3D9 \uC800\uC7A5 \uBC84\uC804\uC744 \uBCF5\uC6D0\uD560\uAE4C\uC694?",
