      errIndexRange: "atIndex \u05DE\u05D7\u05D5\u05E5 \u05DC\u05D8\u05D5\u05D5\u05D7 (0-{max})",
      errReplaceNeedsOne:
        "\u05DE\u05E6\u05D1 replace_at \u05D3\u05D5\u05E8\u05E9 \u05D1\u05D3\u05D9\u05D5\u05E7 \u05E2\u05DE\u05D5\u05D3 HTML \u05D0\u05D7\u05D3",
      errInsertNeedsOne:
        "\u05DE\u05E6\u05D1 insert_at \u05D3\u05D5\u05E8\u05E9 \u05D1\u05D3\u05D9\u05D5\u05E7 \u05E2\u05DE\u05D5\u05D3 HTML \u05D0\u05D7\u05D3",
      errReplaceFailed:
        "\u05D4\u05D7\u05DC\u05E4\u05EA \u05D4\u05E2\u05DE\u05D5\u05D3 \u05D1\u05DE\u05E7\u05D5\u05DE\u05D5 \u05E0\u05DB\u05E9\u05DC\u05D4 (\u05E9\u05D2\u05D9\u05D0\u05D4 \u05D1\u05D4\u05E2\u05D1\u05E8\u05D4/\u05DE\u05D7\u05D9\u05E7\u05D4 \u05E9\u05DC \u05D4\u05E2\u05DE\u05D5\u05D3 \u05D4\u05D9\u05E9\u05DF)",
